/**
 * `node scripts/summarize.js reports/<date>`: the tables of a multi-run
 * report, computed from the run folders it lists (reports/<date>/runs.json),
 * so the report's numbers can be regenerated by anyone with the folders.
 *
 * Writes summary.json and summary.md into the report folder. Accuracy pools
 * errors over reference words (as one run does across rounds); turnaround is
 * summarised from the upper end of each run's window (the poll that saw the
 * job done), and only over runs polled every second.
 */
const fs = require("fs");
const path = require("path");
const { displayName } = require("../src/providers");

const dir = process.argv[2];
if (!dir) throw new Error("Usage: node scripts/summarize.js reports/<date>");
const spec = JSON.parse(fs.readFileSync(path.join(dir, "runs.json"), "utf8"));
const ROOT = path.join(__dirname, "..");

const runs = spec.runs.map((r) => {
  const base = path.join(ROOT, "results", r.id);
  return { ...r, results: JSON.parse(fs.readFileSync(path.join(base, "results.json"), "utf8")), run: JSON.parse(fs.readFileSync(path.join(base, "run.json"), "utf8")) };
});
const providers = [...new Set(runs.flatMap((r) => r.results.providers.map((p) => p.provider)))];
const row = (r, p) => r.results.providers.find((x) => x.provider === p);

const pct = (x) => (x == null ? "–" : `${(x * 100).toFixed(1)}%`);
const s1 = (x) => (x == null ? "–" : `${x.toFixed(1)} s`);
const median = (xs) => { if (!xs.length) return null; const s = [...xs].sort((a, b) => a - b); const m = s.length >> 1; return s.length % 2 ? s[m] : (s[m - 1] + s[m]) / 2; };
const errs = (x) => (x.substitutions ?? 0) + (x.deletions ?? 0) + (x.insertions ?? 0);

// Accuracy, pooled: total errors over total reference words, per provider.
function pooled(subset) {
  return Object.fromEntries(providers.map((p) => {
    const rows = subset.map((r) => row(r, p)).filter((x) => x?.ran && x.wer != null);
    const words = rows.reduce((n, x) => n + x.reference_words, 0);
    const wers = rows.map((x) => x.wer);
    return [p, { runs: rows.length, words, wer: words ? rows.reduce((n, x) => n + errs(x), 0) / words : null, min: wers.length ? Math.min(...wers) : null, max: wers.length ? Math.max(...wers) : null }];
  }));
}
// Same 95% band as one run (src/report.js), on the pooled word count.
const band = (bestWer, words) => (words && Number.isFinite(bestWer) ? 1.96 * Math.sqrt((2 * Math.min(0.5, Math.max(bestWer, 1 / words)) * (1 - Math.min(0.5, Math.max(bestWer, 1 / words)))) / words) : null);

const scored = runs.filter((r) => r.results.reference_words != null);
const sample = scored.filter((r) => r.test === "sample");
const timed = runs.filter((r) => r.results.poll_seconds <= 1);

const turnaround = Object.fromEntries(providers.map((p) => {
  const ups = timed.map((r) => row(r, p)).filter((x) => x?.ran && x.turnaround_median_s != null && x.turnaround_comparable !== false).map((x) => x.turnaround_median_s);
  return [p, { runs: ups.length, median: median(ups), min: ups.length ? Math.min(...ups) : null, max: ups.length ? Math.max(...ups) : null }];
}));
const perHour = Object.fromEntries(providers.map((p) => [p, runs.map((r) => row(r, p)?.cost_per_hour_usd).find((x) => x != null) ?? null]));
const spent = runs.reduce((n, r) => n + r.results.providers.reduce((m, x) => m + (x.cost_usd ?? 0), 0), 0);
const sameEngine = runs.map((r) => ({ id: r.id, identical: !!row(r, "meetstream")?.same_output_as?.includes("jigsawstack") }));

const summary = {
  title: spec.title,
  runs: runs.map((r) => ({ id: r.id, test: r.test, label: r.label, reference_words: r.results.reference_words, poll_seconds: r.results.poll_seconds, harness: r.run.harness_version ?? null, normalizer: r.results.normalizer })),
  accuracy_all: pooled(scored),
  accuracy_sample: pooled(sample),
  turnaround_1s_poll: turnaround,
  per_hour_usd: perHour,
  transcription_spend_usd: spent,
  mia_jigsawstack_identical: sameEngine,
};
fs.writeFileSync(path.join(dir, "summary.json"), JSON.stringify(summary, null, 2) + "\n");

// ── Markdown tables ─────────────────────────────────────────────────────────
const L = [];
const order = (m) => [...providers].sort((a, b) => (m[a].wer ?? 9) - (m[b].wer ?? 9));
const head = (cols, left = 1) => { L.push(`| ${cols.join(" | ")} |`, `|${cols.map((_, i) => (i >= left ? "---:" : "---")).join("|")}|`); };

L.push("### Runs", "");
head(["#", "Test", "Platform", "Run", "Reference words", "Poll", "Harness"], 4);
runs.forEach((r, i) => L.push(`| ${i + 1} | ${r.label} | ${r.platform ?? "–"} | \`${r.id}\` | ${r.results.reference_words ?? "–"} | ${r.results.poll_seconds} s | ${r.run.harness_version?.commit ? `\`${r.run.harness_version.commit.slice(0, 7)}\`` : "not recorded"} |`));

const acc = (title, m, subset) => {
  const words = Math.max(...Object.values(m).map((x) => x.words));
  const best = Math.min(...Object.values(m).map((x) => x.wer).filter((x) => x != null));
  L.push("", `### ${title}`, "");
  head(["Provider", "Pooled WER", "Range over runs", "Runs", "Words"]);
  for (const p of order(m)) L.push(`| ${displayName(p)} | ${pct(m[p].wer)} | ${pct(m[p].min)}–${pct(m[p].max)} | ${m[p].runs} | ${m[p].words} |`);
  L.push("", `Pooled over ${subset.length} runs and ${words} reference words: gaps under ${(band(best, words) * 100).toFixed(1)} points are within sampling noise (95%, treating words as independent).`);
};
acc(`Accuracy, the sample clip (${sample.length} recordings)`, summary.accuracy_sample, sample);
acc("Accuracy, every scored run", summary.accuracy_all, scored);

const platforms = [...new Set(sample.map((r) => r.platform).filter(Boolean))];
if (platforms.length > 1) {
  const byPlatform = Object.fromEntries(platforms.map((pl) => [pl, pooled(sample.filter((r) => r.platform === pl))]));
  summary.accuracy_sample_by_platform = byPlatform;
  L.push("", "### The sample clip on each platform", "");
  head(["Provider", ...platforms.map((pl) => `${pl} (${sample.filter((r) => r.platform === pl).length})`)]);
  for (const p of order(summary.accuracy_sample)) L.push(`| ${displayName(p)} | ${platforms.map((pl) => pct(byPlatform[pl][p].wer)).join(" | ")} |`);
  L.push("", "Pooled WER per platform; the number of recordings is in brackets. One recording on a platform is a single sample: its spread is the same as between recordings on one platform (see Accuracy by run).");
  fs.writeFileSync(path.join(dir, "summary.json"), JSON.stringify(summary, null, 2) + "\n");
}

L.push("", "### Accuracy by run", "");
head(["Provider", ...scored.map((r) => `${runs.indexOf(r) + 1}. ${r.test}`)]);
for (const p of order(summary.accuracy_all)) L.push(`| ${displayName(p)} | ${scored.map((r) => pct(row(r, p)?.wer)).join(" | ")} |`);

L.push("", `### Turnaround, ${timed.length} runs polled every second`, "");
head(["Provider", "Median", "Fastest run", "Slowest run", "Runs"]);
for (const p of [...providers].sort((a, b) => (turnaround[a].median ?? 99) - (turnaround[b].median ?? 99))) {
  L.push(`| ${displayName(p)} | ${s1(turnaround[p].median)} | ${s1(turnaround[p].min)} | ${s1(turnaround[p].max)} | ${turnaround[p].runs} |`);
}
L.push("", "Each value is the poll that first saw the job done (the upper end of its window; the job finished up to 1 s earlier), measured from MeetStream's transcribe request.");

L.push("", "### Turnaround by run (finished within)", "");
head(["Provider", ...timed.map((r) => `${runs.indexOf(r) + 1}. ${r.test}`)]);
for (const p of providers) {
  L.push(`| ${displayName(p)} | ${timed.map((r) => { const x = row(r, p); return x?.turnaround_median_s == null ? "–" : `${x.turnaround_lower_s?.toFixed(1) ?? "≤"}–${x.turnaround_median_s.toFixed(1)}`; }).join(" | ")} |`);
}

L.push("", "### Cost", "");
head(["Provider", "Published rate, per hour of audio"]);
for (const p of [...providers].sort((a, b) => (perHour[a] ?? 9) - (perHour[b] ?? 9))) L.push(`| ${displayName(p)} | ${perHour[p] == null ? "–" : `$${perHour[p].toFixed(2)}`} |`);
L.push("", `Transcription spend for all ${runs.length} runs together: $${spent.toFixed(3)} (MeetStream bot fees not included).`);

fs.writeFileSync(path.join(dir, "summary.md"), L.join("\n") + "\n");
console.log(L.join("\n"));
